def jsonld(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def render(locale, d):
    base = f"https://www.bigfame.co/{locale}/"
    alts = "".join(f'<link rel="alternate" hreflang="{code}" href="https://www.bigfame.co/{loc}/">' for code, loc in (("zh-TW", "tw"), ("en", "en"), ("ja", "jp")))
    org = {"@context": "https://schema.org", "@type": "Organization", "@id": "https://www.bigfame.co/#organization", "name": d["name"], "alternateName": "Big Fame IND. CORP.", "url": "https://www.bigfame.co", "description": d["org_desc"], "address": {"@type": "PostalAddress", "addressLocality": "Taipei", "addressCountry": "TW"}, "contactPoint": {"@type": "ContactPoint", "telephone": "+886-2-2311-8601", "contactType": "sales", "email": "shopdisplay@bigfame.co", "availableLanguage": ["Japanese", "English", "Chinese"]}}
    faq = {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in d["faq"]]}
    audience_html = "".join(f'<article class="location-card reveal"><span class="section-subtitle">{escape(slug.upper())}</span><h3>{escape(title)}</h3><p>{escape(desc)}</p><a class="case-card-link" href="{slug}">{escape(label)}</a></article>' for title, desc, label, slug, href in d["audiences"])
    products_html = "".join(f'<article class="location-card reveal"><span class="section-subtitle">{escape(en_name)}</span><h3><a href="{slug}">{escape(title)}</a></h3><p>{escape(d["hero_span"])} · {escape(title)}</p><a class="case-card-link" href="{slug}">{escape(d["primary"])}</a></article>' for title, en_name, slug in d["products"])
    cases_html = "".join(f'<article class="location-card reveal"><h3><a href="{slug}">{escape(title)}</a></h3><p>{escape(desc)}</p><a class="case-card-link" href="{slug}">{escape(d["cases_title"])}</a></article>' for title, desc, slug in d["cases"])
    process_html = "".join(f'<article class="location-card reveal"><span class="section-subtitle">{num}</span><h3>{escape(title)}</h3><p>{escape(desc)}</p></article>' for num, title, desc in d["process"])
    faq_html = "".join(f'<article class="location-card reveal"><h3>{escape(q)}</h3><p>{escape(a)}</p></article>' for q, a in d["faq"])
    proof_html = "".join(f'<div class="home-proof-item"><strong>{escape(title)}</strong><span>{escape(desc)}</span></div>' for title, desc in d["proof"])
    return f'''<!DOCTYPE html>
<html lang="{d["lang"]}">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="description" content="{escape(d["description"], quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(d["title"], quote=True)}"><meta property="og:description" content="{escape(d["description"], quote=True)}"><meta property="og:url" content="{base}"><meta property="og:site_name" content="Big Fame IND. CORP."><title>{escape(d["title"])}</title><link rel="canonical" href="{base}">{alts}<link rel="alternate" hreflang="x-default" href="https://www.bigfame.co/"><link rel="stylesheet" href="../css/style.css?v={VERSION}"><script type="application/ld+json">{jsonld(org)}</script><script type="application/ld+json">{jsonld(faq)}</script></head>
<body><header class="header"><div class="container navbar"><a href="./" class="logo">BIG FAME<span class="logo-sub">IND. CORP.</span></a><nav class="nav-menu"><a href="./" class="nav-link active">{escape(d["nav"][0])}</a><a href="about" class="nav-link">{escape(d["nav"][1])}</a><a href="products" class="nav-link">{escape(d["nav"][2])}</a><a href="services" class="nav-link">{escape(d["nav"][3])}</a><a href="applications" class="nav-link">{escape(d["nav"][4])}</a><a href="contact?category=integration&role=buyer" class="nav-link nav-cta">{escape(d["nav"][5])}</a></nav><button type="button" class="mobile-toggle" aria-label="Menu" aria-expanded="false"><span></span><span></span><span></span></button></div></header>
<main><section class="hero"><div class="hero-bg hero-bg-fallback" style="background-image:url('../images/hero_display_fixture.jpg');"></div><video class="hero-bg hero-bg-video" autoplay muted loop playsinline preload="metadata" poster="../images/hero_display_fixture.jpg" aria-hidden="true" tabindex="-1"><source src="../videos/hero-apparel-store-blurred-foot-traffic-web-20260804.mp4" type="video/mp4"></video><div class="hero-overlay"></div><div class="container"><div class="hero-content reveal"><span class="hero-tag">{escape(d["tag"])}</span><h1 class="hero-title">{escape(d["hero_title"])}<br><span>{escape(d["hero_span"])}</span></h1><p class="hero-desc">{escape(d["hero_desc"])}</p><div class="btn-group"><a href="products" class="btn btn-primary">{escape(d["primary"])}</a><a href="contact?category=integration&role=buyer" class="btn btn-secondary">{escape(d["secondary"])}</a></div></div></div></section><section class="home-proof"><div class="container home-proof-grid">{proof_html}</div></section>
<section class="section section-light"><div class="container"><div class="section-heading reveal"><span class="section-subtitle">TA ENTRY</span><h2 class="section-title">{escape(d["audience_title"])}</h2></div><div class="grid-3">{audience_html}</div></div></section>
<section class="section section-dark"><div class="container"><div class="section-heading reveal"><span class="section-subtitle">PRODUCTS</span><h2 class="section-title">{escape(d["products_title"])}</h2></div><div class="grid-4">{products_html}</div></div></section>
<section class="section section-light"><div class="container"><div class="section-heading reveal"><span class="section-subtitle">APPLICATIONS &amp; EVIDENCE</span><h2 class="section-title">{escape(d["cases_title"])}</h2></div><div class="grid-3">{cases_html}</div><p class="section-note reveal"><a href="applications">{escape(d["nav"][4])}</a> · <a href="technical-resources">Technical resources / CAD</a></p></div></section>
<section class="section section-light"><div class="container"><div class="section-heading reveal"><span class="section-subtitle">PROCESS</span><h2 class="section-title">{escape(d["process_title"])}</h2></div><div class="grid-4">{process_html}</div></div></section>
<section class="section section-light" data-bf-faq="1"><div class="container"><div class="section-heading reveal"><span class="section-subtitle">FAQ</span><h2 class="section-title">FAQ</h2></div><div class="grid-3">{faq_html}</div></div></section>
<section class="section section-dark"><div class="container"><div class="cta-block reveal"><h2>{escape(d["cta_title"])}</h2><p>{escape(d["cta_desc"])}</p><a class="btn btn-primary" href="contact?category=integration&role=buyer">{escape(d["cta"])}</a></div></div></section></main><footer class="footer"><div class="container footer-bottom"><p>© Big Fame IND. CORP.</p><a href="applications">{escape(d["nav"][4])}</a><a href="contact?category=integration&role=buyer">{escape(d["nav"][5])}</a></div></footer><script src="../js/main.js?v=1.3.23"></script></body></html>'''


for locale, data in DATA.items():
    (ROOT / locale / "index.html").write_text(render(locale, data), encoding="utf-8", newline="\n")
print("Generated readable localized home pages for tw/en/jp")
